import{_ as t,o,c as l,a2 as r}from"./chunks/framework.A5mep7Fe.js";const p=JSON.parse('{"title":"📊 01 · 机器学习基础","description":"","frontmatter":{},"headers":[],"relativePath":"04-算法岗-传统深度学习/01-机器学习基础.md","filePath":"04-算法岗-传统深度学习/01-机器学习基础.md","lastUpdated":1786806808000}'),e={name:"04-算法岗-传统深度学习/01-机器学习基础.md"};function i(n,a,s,c,h,u){return o(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="📊-01-·-机器学习基础" tabindex="-1">📊 01 · 机器学习基础 <a class="header-anchor" href="#📊-01-·-机器学习基础" aria-label="Permalink to &quot;📊 01 · 机器学习基础&quot;">​</a></h1><blockquote><p>算法岗的地基。反向传播能推导、过拟合能讲清，是基础门槛。</p></blockquote><hr><h2 id="一、监督学习三要素" tabindex="-1">一、监督学习三要素 <a class="header-anchor" href="#一、监督学习三要素" aria-label="Permalink to &quot;一、监督学习三要素&quot;">​</a></h2><ul><li><strong>模型</strong>：假设空间（线性/树/神经网络）</li><li><strong>策略</strong>：损失函数（MSE / 交叉熵 / Hinge）</li><li><strong>算法</strong>：优化（梯度下降）</li></ul><h2 id="二、梯度下降与反向传播-⭐-必会" tabindex="-1">二、梯度下降与反向传播（⭐ 必会） <a class="header-anchor" href="#二、梯度下降与反向传播-⭐-必会" aria-label="Permalink to &quot;二、梯度下降与反向传播（⭐ 必会）&quot;">​</a></h2><ul><li><strong>前向</strong>：逐层计算输出与损失</li><li><strong>反向</strong>：链式法则从损失对每层参数求偏导</li><li><strong>更新</strong>：$w \\leftarrow w - \\eta \\nabla_w L$</li><li>变体：BGD / SGD / mini-batch；优化器 SGD / Momentum / Adam（自适应学习率）</li></ul><h2 id="三、过拟合与正则" tabindex="-1">三、过拟合与正则 <a class="header-anchor" href="#三、过拟合与正则" aria-label="Permalink to &quot;三、过拟合与正则&quot;">​</a></h2><ul><li><strong>过拟合</strong>：训练好、测试差。原因：数据少/模型复杂/噪声。</li><li><strong>缓解</strong>：更多数据、正则（L1/L2/Dropout）、早停、数据增强、简化模型、集成。</li><li><strong>偏差-方差权衡</strong>：高偏差→欠拟合；高方差→过拟合。</li></ul><h2 id="四、评估" tabindex="-1">四、评估 <a class="header-anchor" href="#四、评估" aria-label="Permalink to &quot;四、评估&quot;">​</a></h2><ul><li>分类：Accuracy / Precision / Recall / F1 / AUC-ROC</li><li>回归：MSE / MAE / R²</li><li>不平衡数据看 PR 曲线而非 Accuracy</li><li>交叉验证防过拟合估计</li></ul><h2 id="五、经典模型速览" tabindex="-1">五、经典模型速览 <a class="header-anchor" href="#五、经典模型速览" aria-label="Permalink to &quot;五、经典模型速览&quot;">​</a></h2><ul><li>线性/逻辑回归、SVM、决策树、随机森林、GBDT/XGBoost/LightGBM（表格数据王者）</li><li>聚类：K-Means、DBSCAN；降维：PCA、t-SNE</li></ul><h2 id="六、高频追问" tabindex="-1">六、高频追问 <a class="header-anchor" href="#六、高频追问" aria-label="Permalink to &quot;六、高频追问&quot;">​</a></h2><p><strong>Q1：为什么用交叉熵而不是 MSE 做分类？</strong></p><blockquote><p>交叉熵与最大似然一致，梯度更友好；MSE 在 sigmoid 输出下易梯度消失，且分类概率语义不符。</p></blockquote><p><strong>Q2：Adam 一定比 SGD 好吗？</strong></p><blockquote><p>不定。Adam 收敛快但泛化有时不如调好的 SGD；大模型训练多用 AdamW（解耦权重衰减）。</p></blockquote><p><strong>Q3：Dropout 为什么有效？</strong></p><blockquote><p>训练时随机丢弃神经元，等价于训练多个子网络集成，降低神经元共适应，增强泛化。</p></blockquote><hr><p>➡️ 下一步：<a href="./02-计算机视觉CV">02-计算机视觉 CV</a></p>',22)])])}const _=t(e,[["render",i]]);export{p as __pageData,_ as default};
